// Parse filtros do frontend e mapear segmentos → CNAE codes
const body = $input.first().json.body || $input.first().json;
const segments = body.segments || [];
const states = body.states || [];
const city = body.city || '';
const keywords = body.keywords || [];
const revenueMin = parseInt(body.revenueMin) || 70000;
const revenueMax = parseInt(body.revenueMax) || 2000000;

// Segmento (pt-BR) → slug
const SLUG_MAP = {
  'Estética': 'estetica', 'Odontologia': 'odontologia', 'Varejo': 'varejo',
  'Farmácia': 'farmacia', 'Movelaria': 'movelaria', 'Serviços': 'servicos',
  'Alimentação': 'alimentacao', 'Saúde': 'saude', 'Educação': 'educacao',
  'Tecnologia': 'tecnologia', 'Automotivo': 'automotivo', 'Pet Shop': 'petshop',
  'Fitness': 'fitness', 'Beleza': 'beleza', 'Imobiliário': 'imobiliario',
  'Construção': 'construcao', 'Moda': 'moda', 'Decoração': 'decoracao',
  'Agronegócio': 'agronegocio', 'Logística': 'logistica',
};

// Slug → CNAE codes (espelhado de src/lib/cnae-mapping.ts)
const CNAE_MAP = {
  estetica: ['9602-5/01','9602-5/02','8690-9/01'],
  odontologia: ['8630-5/04'],
  varejo: ['4711-3/02','4712-1/00','4789-0/99'],
  farmacia: ['4771-7/01','4771-7/02'],
  movelaria: ['3101-2/00','4754-7/01'],
  servicos: ['6920-6/01','6911-7/01','7020-4/00','7311-4/00'],
  alimentacao: ['5611-2/01','5611-2/03','1091-1/02'],
  saude: ['8630-5/01','8630-5/02','8630-5/03','8650-0/04','8650-0/02'],
  educacao: ['8512-1/00','8531-7/00','8599-6/04','8599-6/05'],
  tecnologia: ['6201-5/01','6202-3/00','6203-1/00','6204-0/00'],
  automotivo: ['4520-0/01','4520-0/04','4530-7/03'],
  petshop: ['4789-0/04','7500-1/00'],
  fitness: ['9313-1/00','9319-1/01'],
  beleza: ['9602-5/01','9602-5/02'],
  imobiliario: ['6821-8/01','6821-8/02','4110-7/00'],
  construcao: ['4120-4/00','4399-1/03','4330-4/01'],
  moda: ['4781-4/00','4782-2/01'],
  decoracao: ['4754-7/01','4759-8/01'],
  agronegocio: ['0111-3/01','4683-4/00','0161-0/01'],
  logistica: ['4930-2/02','5250-8/01','5320-2/02'],
};

const slugs = segments.map(s => SLUG_MAP[s] || s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''));
const cnaeCodes = [...new Set(slugs.flatMap(s => CNAE_MAP[s] || []))];

if (cnaeCodes.length === 0) {
  return [{ json: { error: true, message: 'Nenhum CNAE encontrado para os segmentos selecionados' } }];
}

// Revenue → capital social range
const capitalMin = Math.max(0, Math.round(revenueMin * 0.5));
const capitalMax = Math.round(revenueMax * 5);

return [{
  json: {
    cnaeCodes, states, city, keywords, segments, slugs,
    revenueMin, revenueMax, capitalMin, capitalMax,
    segment: segments[0] || 'Varejo',
    searchId: Date.now().toString(),
    targetCount: 30,
    currentCnaeIndex: 0, currentPage: 1,
    allCompanies: [], seenCnpjs: []
  }
}];

// Montar payload para Casa dos Dados API
const data = $input.first().json;
const cnae = data.cnaeCodes[data.currentCnaeIndex];

const payload = {
  query: {
    termo: [],
    atividade_principal: [cnae],
    natureza_juridica: [],
    uf: data.states.length > 0 ? data.states : [],
    municipio: data.city ? [data.city.toUpperCase()] : [],
    situacao_cadastral: 'ATIVA'
  },
  range_query: {
    capital_social: { gte: data.capitalMin, lte: data.capitalMax }
  },
  extras: {
    somente_mei: false,
    excluir_mei: true,
    com_email: false,
    incluir_atividade_secundaria: false,
    com_contato_telefonico: true
  },
  page: data.currentPage
};

return [{ json: { ...data, currentCnae: cnae, requestPayload: payload } }];

// Processar resultados e decidir se continua buscando
const prev = $('3. Montar Query CNAE').first().json;
const response = $input.first().json;

const companies = response?.data?.cnpj || [];
const allCompanies = [...(prev.allCompanies || [])];
const seenCnpjs = new Set(prev.seenCnpjs || []);

let newCount = 0;
for (const c of companies) {
  const cleanCnpj = (c.cnpj || '').replace(/\D/g, '');
  if (!cleanCnpj || seenCnpjs.has(cleanCnpj)) continue;
  seenCnpjs.add(cleanCnpj);
  newCount++;
  allCompanies.push({
    cnpj: cleanCnpj,
    razao_social: c.razao_social || '',
    nome_fantasia: c.nome_fantasia || '',
    cnae_fiscal_descricao: c.cnae_fiscal_descricao || '',
    cnae_fiscal: c.cnae_fiscal || '',
    uf: c.uf || '',
    municipio: c.municipio || '',
    logradouro: c.logradouro || '',
    numero: c.numero || '',
    bairro: c.bairro || '',
    capital_social: c.capital_social || 0,
    porte: c.porte || '',
    data_inicio_atividade: c.data_inicio_atividade || '',
    telefone1: c.ddd_telefone_1 || c.telefone1 || '',
    telefone2: c.ddd_telefone_2 || c.telefone2 || '',
    email: c.correio_eletronico || c.email || '',
    qsa: (c.qsa || []).map(s => ({
      nome_socio: s.nome_socio || s.nome || '',
      qualificacao_socio: s.qualificacao_socio || s.qual || ''
    }))
  });
}

const hasMorePages = newCount > 0 && prev.currentPage < 5;
const needsMore = allCompanies.length < prev.targetCount;
const hasMoreCnaes = prev.currentCnaeIndex < prev.cnaeCodes.length - 1;

let nextPage = prev.currentPage;
let nextCnaeIndex = prev.currentCnaeIndex;
let continueLoop = false;

if (needsMore && hasMorePages) {
  nextPage = prev.currentPage + 1;
  continueLoop = true;
} else if (needsMore && hasMoreCnaes) {
  nextCnaeIndex = prev.currentCnaeIndex + 1;
  nextPage = 1;
  continueLoop = true;
}

return [{ json: {
  ...prev,
  allCompanies,
  seenCnpjs: Array.from(seenCnpjs),
  currentPage: nextPage,
  currentCnaeIndex: nextCnaeIndex,
  continueLoop,
  totalFound: allCompanies.length
} }];

// Enriquecer cada CNPJ via BrasilAPI (sem rate limit) + OpenCNPJ fallback
const data = $input.first().json;
const companies = data.allCompanies || [];

for (let i = 0; i < companies.length; i++) {
  const c = companies[i];
  try {
    // BrasilAPI — sem rate limit, retorna QSA, telefone, email
    const res = await fetch('https://brasilapi.com.br/api/cnpj/v1/' + c.cnpj, { signal: AbortSignal.timeout(8000) });
    if (res.ok) {
      const d = await res.json();
      const socios = (d.qsa || []).map(s => ({
        nome_socio: s.nome_socio || s.nome || '',
        qualificacao_socio: s.qualificacao_socio || s.qual || ''
      }));
      const phones = [d.ddd_telefone_1, d.ddd_telefone_2].filter(Boolean)
        .flatMap(p => p.split(/[\/;,]/))
        .map(p => p.trim().replace(/\D/g, ''))
        .filter(p => p.length >= 10);
      if (socios.length > 0) c.qsa = socios;
      if (phones[0]) c.telefone1 = phones[0];
      if (phones[1]) c.telefone2 = phones[1];
      c.email = d.email || d.correio_eletronico || c.email;
      c.capital_social = d.capital_social || c.capital_social;
      c.nome_fantasia = d.nome_fantasia || c.nome_fantasia;
      c.porte = d.descricao_porte || c.porte;
    }
  } catch {}
  // Small delay to be respectful
  if (i < companies.length - 1 && i % 8 === 7) await new Promise(r => setTimeout(r, 500));
}

return [{ json: { ...data, allCompanies: companies } }];

// Classificar telefones, extrair decisor, scoring, filtrar top 15
const data = $input.first().json;
const companies = data.allCompanies || [];
const MAX_LEADS = 15;

function classifyPhone(phone) {
  const d = phone.replace(/\D/g, '');
  const w = d.startsWith('55') ? d.slice(2) : d;
  if (w.length === 11 && w[2] === '9') return 'mobile';
  if (w.length === 10 && w[2] === '9') return 'mobile';
  return 'landline';
}

function formatPhone(phone) {
  let d = phone.replace(/\D/g, '').replace(/^0+/, '');
  const w = d.startsWith('55') ? d.slice(2) : d;
  if (w.length === 10 && w[2] === '9') {
    d = w.slice(0, 2) + '9' + w.slice(2);
    return '55' + d;
  }
  return d.length >= 10 ? (d.startsWith('55') ? d : '55' + d) : d;
}

const leads = companies.map(c => {
  const socios = c.qsa || [];
  const decisor = socios.find(s =>
    (s.qualificacao_socio||'').toLowerCase().match(/administrador|diretor|presidente|s[oó]cio/)
  ) || socios[0];

  const phones = [c.telefone1, c.telefone2].filter(Boolean)
    .flatMap(p => p.split(/[\/;,]/))
    .map(p => p.trim().replace(/\D/g, ''))
    .filter(p => p.length >= 10);
  const mobile = phones.find(p => classifyPhone(p) === 'mobile');
  const whatsapp = mobile ? formatPhone(mobile) : '';
  const mainPhone = phones[0] ? formatPhone(phones[0]) : '';

  const capital = c.capital_social || 0;
  const revenue = capital > 0 ? Math.round(capital * 1.5) : 70000;
  const tier = revenue >= 830000 ? 'Medium=' : revenue >= 200000 ? 'Medium-' : revenue >= 100000 ? 'Small' : 'Micro+';
  const yearsInMarket = c.data_inicio_atividade
    ? Math.max(1, new Date().getFullYear() - new Date(c.data_inicio_atividade).getFullYear())
    : 5;
  const employees = c.porte === 'DEMAIS' ? 20 : c.porte === 'PEQUENO' ? 10 : 5;

  // Pre-SPICED scoring
  const hasDecisor = !!(decisor?.nome_socio);
  const hasMobile = !!mobile;
  const hasEmail = !!c.email;
  const spicedS = Math.min(1 + (yearsInMarket >= 5 ? 1 : 0) + (capital >= 100000 ? 1 : 0) + (employees >= 8 ? 1 : 0), 5);
  const spicedP = Math.max(5 - (capital >= 500000 ? 1 : 0) - (employees >= 10 ? 1 : 0), 1);
  const spicedI = hasMobile ? 4 : hasEmail ? 3 : 2;
  const spicedC = hasDecisor ? 4 : 3;
  const spicedD = hasEmail ? 4 : mainPhone ? 3 : 2;
  const score = Math.round((spicedS*0.25 + spicedP*0.25 + spicedI*0.20 + spicedC*0.15 + spicedD*0.15) * 10) / 10;
  const temperatura = score >= 4 ? 'Quente' : score >= 3 ? 'Morno' : 'Frio';

  let trap = 'T1 - Aquisição de clientes';
  if (capital >= 200000) trap = 'T6 - Posicionamento de marca';
  else if (!hasMobile && !hasEmail) trap = 'T2 - Conversão de vendas';

  return {
    companyName: c.nome_fantasia || c.razao_social,
    tradeName: c.nome_fantasia,
    cnpj: c.cnpj,
    segment: data.segment || c.cnae_fiscal_descricao,
    tier, monthlyRevenue: revenue, employees, yearsInMarket,
    status: 'Novo', score, temperatura,
    spicedS, spicedP, spicedI, spicedC, spicedD,
    hypotheticalTrap: trap,
    website: '', instagram: '', linkedin: '', facebook: '',
    address: [c.logradouro, c.numero, c.bairro].filter(Boolean).join(', '),
    city: c.municipio, state: c.uf,
    googleRating: 0, googleReviewsCount: 0,
    capitalSocial: capital, foundingDate: c.data_inicio_atividade || '',
    cnaePrimary: c.cnae_fiscal, partners: JSON.stringify(c.qsa || []),
    rfEmail: c.email || '', rfPhone: mainPhone,
    businessSummary: `${data.segment || c.cnae_fiscal_descricao} · CNPJ: ${c.cnpj} · Capital: R$ ${(capital/1000).toFixed(0)}k · ${hasDecisor ? 'Decisor: ' + decisor.nome_socio : 'Sem decisor'}`,
    enrichmentStatus: 'pending',
    // Dados para Contact (prefixo _)
    _whatsapp: whatsapp,
    _phone: mainPhone,
    _email: c.email || '',
    _ownerName: decisor?.nome_socio || c.razao_social,
    _ownerRole: decisor?.qualificacao_socio || 'Sócio',
    _isMobile: !!mobile,
    // Dados internos para Claude (rating/reviews do Google Maps = 0 neste pipeline)
    rating: 0, reviews: 0, revenue: revenue,
  };
}).filter(l => l.monthlyRevenue >= data.revenueMin * 0.5 && l.monthlyRevenue <= data.revenueMax * 1.5);

// Sort: WhatsApp first, then by score
leads.sort((a, b) => {
  if (a._isMobile && !b._isMobile) return -1;
  if (!a._isMobile && b._isMobile) return 1;
  return b.score - a.score;
});

const finalLeads = leads.slice(0, MAX_LEADS);

if (finalLeads.length === 0) {
  return [{ json: { success: true, leadsCreated: 0, totalFound: companies.length, message: 'Nenhum lead na faixa de faturamento' } }];
}

return finalLeads.map(lead => ({ json: lead }));

